params.script:
const root = await tools.glob_search({ pattern: 'docs/*.md', max_results: 100 });
const locales = ['ja', 'ko', 'es', 'pt-br', 'ru', 'zh-hans', 'zh-hant'];
const pages = root.files.map((file) => file.split('/').pop()).filter((name) => name !== 'index.md');
const missing = {};
for (const locale of locales) {
  const files = await tools.glob_search({ pattern: 'docs/' + locale + '/*.md', max_results: 100 });
  const names = new Set(files.files.map((file) => file.split('/').pop()));
  missing[locale] = pages.filter((page) => !names.has(page));
}
console.log('Root pages:', pages.length + 1);
console.log('Missing localized routes:', JSON.stringify(missing));
return { pages, missing };

